import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import { Modal } from "antd";
import logisticsApi from "../../../api/logistics/logisticsApi";

export default function EntityStoreFormModal({
  openFormModal,
  setopenFormModal,
  entityStore,
  setUpdated,
  updated
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, loggedInUser } = useStateContext();





  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const entityStoreActionApi = useApi(logisticsApi.logisticsAdminAction);
  const handleEntityStoreAction = async (data) => {
    await entityStoreActionApi.request(data);
  };

  useEffect(() => {
    if (entityStoreActionApi.data) {
      if (entityStoreActionApi.data.entity_store) {
        toast.success(entityStoreActionApi.data.response_message);
        setUpdated(true)
        setopenFormModal(false)
      } else {
        toast.error(entityStoreActionApi.data.response_message);
      }
    }
    console.log("entityStoreActionApi.data",entityStoreActionApi.data)
  }, [entityStoreActionApi.data]);


  
  const formik = useFormik({
    initialValues: {
      title: entityStore ? entityStore.title : "",
      description: entityStore ? entityStore.description : "",
     
    },

    validationSchema: Yup.object({
      title: Yup.string().required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action
      let data = null;
      console.log("VALZ",values)

      if (entityStore) {
        data = {
          action: "UpdateEntityStore",
          entity_store: entityStore.id,
          title: values.title,
          description: values.description,
        };
      } else {
        data = {
          action: "CreateEntityStore",
       
            title: values.title,
            description: values.description,
          
        };
      }

      handleEntityStoreAction(data);

      resetForm();
    },
  });

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setopenFormModal(false);
  };
  const handleCancel = () => {
    setopenFormModal(false);
  };

  return (
    <div className=" max-w-fit min-w-fit">
      <ToastContainer theme="colored" position="bottom-center" />
      <Modal
        width={600}
        className="w-full text-center capitalize"
        title={
          entityStore
            ? "EDIT " + entityStore.title
            : "ADD NEW DEPARTMENT"
        }
        open={openFormModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
            className="w-full"
          >
            <CustomInput
              id="title"
              name="title"
              required={true}
              onChange={formik.handleChange}
              placeholder="Enter title"
              label="Enter title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
            className="w-full"
          >
            <CustomTextArea
              rows={2}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Any description"
              label="Any description"
              size="large"
              type="text"
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
