import React, { useEffect, useState } from 'react'
import StoresTable from './StoresTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import frequenciesApi from '../../../api/drugs/frequenciesApi';
import { Loading } from '../../../components';
import EntityStoreFormModal from './EntityStoreFormModal';
import logisticsApi from '../../../api/logistics/logisticsApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function EntityStoresList() {
    const [openFormModal, setopenFormModal] = useState(false)

    const navigate = useNavigate()
    const [entityStore, setEntityStore] = useState()
    const [entityStores, setEntityStores] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const entityStoresActionsApi = useApi(logisticsApi.logisticsAdminAction)

    const getEntityStores = async () => {
        await entityStoresActionsApi.request({
            "action": "GetEntityStores"

        })
    }


    useEffect(() => {
        getEntityStores()
    }, [])


    const handleEditAction = (item) => {

        setopenFormModal(true)
        setEntityStore(item)
        setmodalTitle(`Edit ${item.title}`)
        setUpdated(false)

    }

    const handleAddAction = () => {
        setopenFormModal(true)
        setmodalTitle("Add new body system")
        setEntityStore(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (entityStoresActionsApi.data && entityStoresActionsApi.data.length) {

            setEntityStores(entityStoresActionsApi.data)
        }
    }, [entityStoresActionsApi.data])

    useEffect(() => {
        if (updated != null)
            getEntityStores()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(entityStores)
    }, [entityStores])


    const handleFilter = (e) => {
        const search_param = e
        if (entityStores && entityStores.length > 0 && search_param && search_param !== '') {
            setdata(entityStores.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(entityStores);
        }

    };

    return entityStoresActionsApi.loading ? <Loading loading={frequenciesApi.loading} /> : (
        <div className='mt-16 md:mt-2'>
            {openFormModal && <EntityStoreFormModal openFormModal={openFormModal} setopenFormModal={setopenFormModal} entityStore={entityStore} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <StoresTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default EntityStoresList